import 'package:flutter/material.dart';
import '../../services/mobile_api_service.dart';

class CreateMeetingScreen extends StatefulWidget { const CreateMeetingScreen({super.key, this.meeting}); final Map<String,dynamic>? meeting; @override State<CreateMeetingScreen> createState()=>_CreateMeetingScreenState(); }
class _CreateMeetingScreenState extends State<CreateMeetingScreen>{ final title=TextEditingController(), agenda=TextEditingController(); DateTime date=DateTime.now(); TimeOfDay time=TimeOfDay.now(); bool saving=false; @override void dispose(){title.dispose();agenda.dispose();super.dispose();} Future<void> save()async{if(title.text.trim().isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Enter a meeting title.')));return;}setState(()=>saving=true);try{await MobileApiService.createMeeting(title:title.text.trim(),agenda:agenda.text.trim().isEmpty?null:agenda.text.trim(),meetingDate:date,meetingTime:TimeOfDayData(hour:time.hour,minute:time.minute));if(mounted)Navigator.pop(context,true);}on MobileApiException catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.message)));}finally{if(mounted)setState(()=>saving=false);}} @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Create Meeting')),body:ListView(padding:const EdgeInsets.all(20),children:[Text('Schedule a video meeting',style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:20),TextField(controller:title,decoration:const InputDecoration(labelText:'Meeting title')),const SizedBox(height:14),TextField(controller:agenda,maxLines:4,decoration:const InputDecoration(labelText:'Agenda (optional)')),const SizedBox(height:20),OutlinedButton.icon(onPressed:()async{final d=await showDatePicker(context:context,initialDate:date,firstDate:DateTime.now().subtract(const Duration(days:1)),lastDate:DateTime.now().add(const Duration(days:365)));if(d!=null)setState(()=>date=d);},icon:const Icon(Icons.calendar_today),label:Text('Date: ${date.year}-${date.month}-${date.day}')),OutlinedButton.icon(onPressed:()async{final t=await showTimePicker(context:context,initialTime:time);if(t!=null)setState(()=>time=t);},icon:const Icon(Icons.schedule),label:Text('Time: ${time.format(context)}')),const SizedBox(height:28),FilledButton(onPressed:saving?null:save,child:Text(saving?'Saving...':'Create Meeting'))])); }

